def removezero_ip(ip):
    # Split the IP address by dots
    segments = ip.split('.')

    # Validate if the IP has exactly 4 segments
    if len(segments) != 4:
        raise ValueError("Invalid IP address format: must have exactly 4 segments.")

    # Process each segment
    cleaned_segments = []
    for segment in segments:
        # Ensure the segment is numeric
        if not segment.isdigit():
            raise ValueError(f"Invalid segment '{segment}': must be numeric.")

        # Convert to integer to remove leading zeroes and back to string
        cleaned_segment = str(int(segment))
        cleaned_segments.append(cleaned_segment)

    # Reassemble the cleaned IP address
    return '.'.join(cleaned_segments)

# Example test cases
if __name__ == "__main__":
    # Valid cases
    assert removezero_ip("216.08.094.196") == "216.8.94.196"
    assert removezero_ip("192.168.001.001") == "192.168.1.1"
    assert removezero_ip("000.000.000.000") == "0.0.0.0"
    assert removezero_ip("255.255.255.255") == "255.255.255.255"

    # Invalid cases
    try:
        removezero_ip("192..168.1.1")
    except ValueError as e:
        assert str(e) == "Invalid IP address format: must have exactly 4 segments."

    try:
        removezero_ip("192.168.1")
    except ValueError as e:
        assert str(e) == "Invalid IP address format: must have exactly 4 segments."

    try:
        removezero_ip("192.168.one.1")
    except ValueError as e:
        assert str(e) == "Invalid segment 'one': must be numeric."

    try:
        removezero_ip("")
    except ValueError as e:
        assert str(e) == "Invalid IP address format: must have exactly 4 segments."

    print("All tests passed!")
